// Level 1 lesson data: src/content_level1.json is generated by scripts/export_content.py from level1/curriculum/*.md.
import raw from './content_level1.json'
import type { WordCard } from './ui'
export interface L1Section { id: string; title: string; kind: 'page' | 'words' | 'listening'; html: string; htmlAfter?: string }
export interface L1Download { kind: 'pdf' | 'docx' | 'pptx' | 'mp3'; href: string; label: string; size: number }
export interface L1Lesson {
  n: number; week: number; title: string; focusHtml: string; function: string; ready: boolean
  // only when ready (a Level1_Lesson<N>.md exists):
  topic?: string; words?: WordCard[]; audio?: string; audioSize?: number; sections?: L1Section[]; teacher?: string
  downloads?: L1Download[]; slides?: string
}
export interface L1Milestone { week: number; title: string; note: string }
export interface L1Content { semester: string; routine: string; lessons: L1Lesson[]; milestones: L1Milestone[]; credit: string; creditHtml: string }
export const level1 = raw as L1Content
export const readyLessons = level1.lessons.filter(l => l.ready)
